const STRING_HASH_CACHE_MAX_SIZE = 255;
let stringHashCacheSize = 0;
let stringHashCache = {};

function coordinatorLane(prefix, index) {
  const label = String(index);
  return prefix + (label.length < 2 ? '0' + label : label);
}

export class Collection {
  constructor(value) {
    // eslint-disable-next-line no-constructor-return
    return isCollection(value) ? value : Seq(value);
  }


  computeValueHash(o) {
    this._hashKind = 0;
    this._hashScratch = 0;
    let hashed;
    if (o == null) {
      hashed = this.hashNullishValue(o);
    } else if (typeof o.hashCode === 'function') {
      hashed = this.hashHashableValue(o);
    } else {
      const unwrapped = this.unwrapHashedValue(o);
      if (unwrapped == null) {
        hashed = this.hashNullishValue(unwrapped);
      } else {
        hashed = this.dispatchValueHash(unwrapped);
      }
    }
    this.inspectHashSupport(o, hashed);
    return hashed;
  }

  unwrapHashedValue(obj) {
    this._hashScratch = this._hashScratch | 0;
    if (obj.valueOf !== defaultValueOf && typeof obj.valueOf === 'function') {
      return obj.valueOf(obj);
    }
    return obj;
  }

  dispatchValueHash(value) {
    const valueType = typeof value;
    this._hashKind = this.classifyHashType(valueType, value);
    if (valueType === 'boolean') {
      return this.hashBooleanValue(value);
    }
    if (valueType === 'number') {
      return this.hashNumberValue(value);
    }
    if (valueType === 'string') {
      return this.hashStringValue(value);
    }
    if (valueType === 'object' || valueType === 'function') {
      return this.hashObjectValue(value);
    }
    if (valueType === 'symbol') {
      return this.hashSymbolValue(value);
    }
    return this.hashUnknownValue(value);
  }

  classifyHashType(valueType, value) {
    this._hashKind = 0;
    if (valueType === 'boolean') {
      this._hashKind = value ? 2 : 1;
    } else if (valueType === 'number') {
      this._hashKind = 3;
    } else if (valueType === 'string') {
      this._hashKind = 4;
    } else if (valueType === 'symbol') {
      this._hashKind = 5;
    } else if (valueType === 'function') {
      this._hashKind = 6;
    } else {
      this._hashKind = 7;
    }
    return this._hashKind;
  }

  hashNullishValue(nullish) {
    this._hashKind = nullish === null ? 8 : 9;
    if (nullish === null) {
      return 0x42108422;
    }
    return 0x42108423;
  }

